package net.fodoth.skina.neoguanniao.network;
import net.fodoth.skina.neoguanniao.client.camera.PhotoClientRepository; import net.minecraft.network.RegistryFriendlyByteBuf; import net.minecraft.network.codec.StreamCodec; import net.minecraft.network.protocol.common.custom.CustomPacketPayload; import net.minecraft.resources.ResourceLocation; import net.neoforged.neoforge.network.handling.IPayloadContext; import org.jetbrains.annotations.NotNull;
public record PhotoDownloadStartPacket(String photoId,boolean found,int totalBytes,int width,int height,String contentHash) implements CustomPacketPayload { public static final Type<PhotoDownloadStartPacket> TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath("neoguanniao","photo_download_start")); public static final StreamCodec<RegistryFriendlyByteBuf,PhotoDownloadStartPacket> STREAM_CODEC=StreamCodec.of((b,p)->{b.writeUtf(p.photoId,80);b.writeBoolean(p.found);b.writeVarInt(p.totalBytes);b.writeVarInt(p.width);b.writeVarInt(p.height);b.writeUtf(p.contentHash,64);},b->new PhotoDownloadStartPacket(b.readUtf(80),b.readBoolean(),b.readVarInt(),b.readVarInt(),b.readVarInt(),b.readUtf(64))); public static PhotoDownloadStartPacket missing(String id){return new PhotoDownloadStartPacket(id,false,0,0,0,"");} public static void handle(PhotoDownloadStartPacket p,IPayloadContext c){c.enqueueWork(()->PhotoClientRepository.beginDownload(p.photoId,p.found,p.totalBytes,p.width,p.height,p.contentHash));} @Override public @NotNull Type<? extends CustomPacketPayload> type(){return TYPE;} }
